ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
	"recordTypeQuery" :"SELECT Id from RecordType where DeveloperName = 'Associate' and SobjectType = 'Contact'"
}

%dw 2.0
output application/json
---
vars.empsContactDetails ++ ((payload filter ((item, index) -> item.EmployeeNumber != null) ) map ((item, index) ->
{
    "EmpId" : item.EmployeeNumber,
    "Id" : item.Id
}
))

%dw 2.0
output application/json
---
vars.empsAccountsDetails ++ ((payload filter ((item, index) -> item.Baird_BU_ID__c != null) ) map ((item, index) ->
{
    "BUid" : item.Baird_BU_ID__c,
    "Id" : item.Id
}
))

ee:message.ee:set-payload:
%dw 2.0
import * from dw::core::Arrays
output application/json
var partitioned = payload partition ((item) -> 
	((item.Emails == null or (((item.Emails filter($.EmailAddressTypeCode == "BRDEMAIL")).EmailAddress[0]) == null)) or 
		(item.FirstName == null or isEmpty(item.FirstName)) or 
		(item.LastName == null or isEmpty(item.LastName)) or 
		(item.UserName == null or isEmpty(item.UserName)) or 
		(item.EmpId == null or isEmpty(item.EmpId)) or
		((isEmpty(item.EmploymentDetail.HireDate)) or item.EmploymentDetail.HireDate > (now() as Date)) 

		//or 
		//(item.EmploymentDetail.Active == false and !(vars.userEmployeeNumbers.EmployeeNumber contains item.EmpId))
		)
)
---
{
	invalidWorkersData: partitioned[0],
	validWorkersData: partitioned[1]
}
